DROP TABLE IF EXISTS `policy`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `policy` (
  `POLICY_ID` bigint NOT NULL AUTO_INCREMENT,
  `POLICY_NAME` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `POLICY_SLUG` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `POLICY_VALUE` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `POLICY_DISPLAY_NAME` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `POLICY_REMARK` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `POLICY_ENABLED` tinyint(1) NOT NULL DEFAULT '1',
  `CREATED_DT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `MODIFIED_DT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`POLICY_ID`),
  UNIQUE KEY `POLICY_NAME` (`POLICY_NAME`),
  KEY `idx_policy_name` (`POLICY_NAME`),
  KEY `idx_policy_slug` (`POLICY_SLUG`)
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

